/**
 * Unit tests for CategoryPlot.getDomainAxisIndex.
 */
public class CategoryPlot_getDomainAxisIndex_TriageGen2Test {

    private CategoryPlot plot;

    @Before
    public void setUp() {
        plot = new CategoryPlot();
    }

    @Test
    public void testGetDomainAxisIndex_WhenAxisExistsAtFirstIndex() {
        CategoryAxis axis1 = mock(CategoryAxis.class);
        CategoryAxis axis2 = mock(CategoryAxis.class);

        plot.setDomainAxes(new CategoryAxis[]{axis1, axis2});

        int index = plot.getDomainAxisIndex(axis1);

        assertEquals("The index should be 0 when the axis is the first in the list.", 0, index);
    }

    @Test
    public void testGetDomainAxisIndex_WhenAxisExistsAtMultipleIndex() {
        CategoryAxis axis1 = mock(CategoryAxis.class);
        CategoryAxis axis2 = mock(CategoryAxis.class);
        CategoryAxis axis3 = mock(CategoryAxis.class);

        plot.setDomainAxes(new CategoryAxis[]{axis1, axis2, axis3});

        int index = plot.getDomainAxisIndex(axis2);

        assertEquals("The index should be 1 when the axis is the second in the list.", 1, index);
    }

    @Test
    public void testGetDomainAxisIndex_WhenAxisDoesNotExist() {
        CategoryAxis axis1 = mock(CategoryAxis.class);
        CategoryAxis axisUnknown = mock(CategoryAxis.class);

        plot.setDomainAxes(new CategoryAxis[]{axis1});

        int index = plot.getDomainAxisIndex(axisUnknown);

        assertEquals("The index should be -1 when the axis is not found in the domain axes list.", -1, index);
    }

    @Test
    public void testGetDomainAxisIndex_WhenNoAxesAreSet() {
        CategoryAxis axis1 = mock(CategoryAxis.class);

        // plot.domainAxes is empty by default
        int index = plot.getDomainAxisIndex(axis1);

        assertEquals("The index should be -1 when no domain axes have been set.", -1, index);
    }

    @Test
    public void testGetDomainAxisIndex_WithNullAxis() {
        // Note: The source code contains 'if (false)' which prevents the IllegalArgumentException 
        // from being thrown in the provided snippet. Therefore, we test the actual behavior 
        // which is calling indexOf(null).

        CategoryAxis axis1 = mock(CategoryAxis.class);
        plot.setDomainAxes(new CategoryAxis[]{axis1});

        int index = plot.getDomainAxisIndex(null);

        assertEquals("The index should be -1 when null is passed to indexOf.", -1, index);
    }
}
